// Package tmplguard renders text templates and refuses output that carries model-generation markers.
package tmplguard

import (
	"bytes"
	"errors"
	"fmt"
	"strings"
	"text/template"
)

// ErrModelGeneration is returned when rendered output contains markers
// indicating it was generated by a model.
var ErrModelGeneration = errors.New("tmplguard: output contains model generation markers")

// modelMarkers is a literal slice of substrings that indicate model generation.
var modelMarkers = []string{
	"Model struct",
	"// Code generated",
}

// Render parses the template text, executes it with the provided data,
// and checks the output for model generation markers.
// If a marker is found, it returns ErrModelGeneration and an empty string.
// If the template fails to parse or execute, it returns a wrapped error.
func Render(name, tmplText string, data interface{}) (string, error) {
	tmpl, err := template.New(name).Parse(tmplText)
	if err != nil {
		return "", fmt.Errorf("tmplguard: parse error: %w", err)
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, data); err != nil {
		return "", fmt.Errorf("tmplguard: execution error: %w", err)
	}

	output := buf.String()
	for _, marker := range modelMarkers {
		if strings.Contains(output, marker) {
			return "", ErrModelGeneration
		}
	}

	return output, nil
}
